-- In-session → Help Request scenario — Happy Path
-- Stable keys map to fixed UUIDs in src/data/helpRequestHappyPathFallback.ts

update public.scenarios
set
  summary = 'Tutors receive and resolve student help requests during the session.',
  layout = 'stacked'
where id = 'a0000000-0000-4000-8000-000000000205';

insert into public.paths (id, scenario_id, name, summary, kind)
values (
  'a0000000-0000-4000-8000-00000000080d',
  'a0000000-0000-4000-8000-000000000205',
  'Happy Path',
  'Tutors receive and resolve student help requests during the session.',
  'happy'
)
on conflict (id) do update set
  scenario_id = excluded.scenario_id,
  name = excluded.name,
  summary = excluded.summary,
  kind = excluded.kind;

